// Patient-facing presentation preferences. Medical source text stays attributed.
const palettes=[['sage','Clinical sage','#245e50','#edf4eb'],['ocean','Coastal blue','#316b89','#e7f0f8'],['lavender','Soft lavender','#665184','#f1edf7'],['sand','Warm linen','#775d40','#f5efe5'],['teal','Quiet teal','#126d70','#e5f4f1'],['rose','Muted rose','#8b5063','#f8edf0'],['night','Night garden','#a9d5bb','#293e32'],['midnight','Midnight blue','#9cc9ee','#233449']];
simple=get('prognos-simple',true);
function preference(key,value){put('prognos-'+key,value);if(key==='simple')simple=value;if(key==='atlas')atlasMode=value;applySettings();render()}
const originalApply=applySettings;
applySettings=function(){originalApply();document.body.dataset.texture=get('prognos-texture','contour');document.body.dataset.spacing=get('prognos-spacing','relaxed');document.body.classList.toggle('reduce-motion',get('prognos-motion',false));document.body.classList.toggle('reading-focus',get('prognos-focus',false));document.body.style.setProperty('--reading-size',get('prognos-large',false)?'19px':'16px');document.body.style.setProperty('--reading-width',get('prognos-width','comfortable')==='narrow'?'60ch':'76ch')};
const savedSettings=settings;
settings=function(){return `${title('A CALMER SPACE FOR YOUR HEALTH','Make room for clarity.','Personalize your palette, reading comfort and exploration preferences. Saved on this device.')}<section class="card"><h2>Your color palette</h2><p class="muted">Quiet colors, clear contrast and a consistent medical workspace.</p><div class="palette-grid">${palettes.map(([k,n,a,b])=>`<button class="palette ${get('prognos-theme','sage')===k?'selected':''}" aria-pressed="${get('prognos-theme','sage')===k}" onclick="preference('theme','${k}')"><span class="palette-preview" style="background:${b};border-color:${a}"><i style="background:${a}">+</i><span style="background:${a}"></span></span><b>${n}</b>${get('prognos-theme','sage')===k?' ':''}</button>`).join('')}</div></section><section class="card comfort-controls"><h2>Reading & surroundings</h2>${selectPreference('Background detail','texture',[['contour','Soft contours'],['grid','Clinical grid'],['plain','Solid calm']],'contour')}${selectPreference('Reading width','width',[['comfortable','Comfortable'],['narrow','Focused column']],'comfortable')}${selectPreference('Content spacing','spacing',[['relaxed','Room to breathe'],['compact','Compact']],'relaxed')}${selectPreference('Default body explorer','atlas',[['simple','Simple body map'],['detailed','Detailed 3D atlas']],'simple')}<div class="preference-toggles">${[['large','Larger reading text',false],['simple','Short overviews first',true],['motion','Reduce animation',false],['focus','Hide decorative artwork',false]].map(([k,n,d])=>`<label><input type="checkbox" ${get('prognos-'+k,d)?'checked':''} onchange="preference('${k}',this.checked)"> ${n}</label>`).join('')}</div><button class="secondary" onclick="if('speechSynthesis' in window)speechSynthesis.cancel()">Stop reading aloud</button></section><section class="card"><h2>Your saved reading</h2>${saved.length?`<div class="condition-grid">${saved.map(id=>directoryById.has(id)?directoryCard(directoryById.get(id)):conditionCards(DATA.conditions.filter(c=>c.id===id))).join('')}</div>`:'<p>Use “Save” on any condition page to keep your reading together here.</p>'}<p class="muted">Preferences and medicine schedules stay in this browser. They are not an encrypted medical record or synced account.</p><button class="secondary" onclick="clearData()">Clear my saved information</button></section>`};
function selectPreference(label,key,options,fallback){return `<label class="preference-row">${label}<select onchange="preference('${key}',this.value)">${options.map(([v,n])=>`<option value="${v}" ${get('prognos-'+key,fallback)===v?'selected':''}>${n}</option>`).join('')}</select></label>`}
let atlasMode=get('prognos-atlas','simple'),bodySide='front',chosenRegion='';
function setAtlas(mode){atlasMode=mode;render()}
function simpleBody(){const back=bodySide==='back';const zone=(r,shape)=>`<g data-region="${r}" role="button" tabindex="0" aria-label="Explore ${r.toLowerCase()}" class="body-zone ${chosenRegion===r?'active':''}"><title>${r}</title>${shape}</g>`;return `<div class="simple-atlas"><div class="body-illustration"><svg viewBox="0 0 320 510" role="group" aria-label="${back?'Back':'Front'} of body. Select a general area of discomfort."><path class="body-axis" d="M160 15v480M30 250h260"/>${zone('Head','<ellipse cx="160" cy="57" rx="35" ry="42"/><rect x="147" y="93" width="26" height="25" rx="10"/>')}${zone(back?'Back':'Chest','<path d="M120 116 Q160 103 200 116 L198 195 Q160 214 122 195Z"/>')}${zone(back?'Back':'Abdomen','<path d="M122 201 Q160 218 198 201 L198 270 Q160 288 122 270Z"/>')}${zone('Pelvis','<path d="M122 277 Q160 294 198 277 L204 316 L160 332 L116 316Z"/>')}${zone('Arms','<path d="M113 119 Q92 119 88 143 L66 267 L54 301 Q51 316 63 319 Q77 319 80 304 L90 276 L121 163Z"/><path d="M207 119 Q228 119 232 143 L254 267 L266 301 Q269 316 257 319 Q243 319 240 304 L230 276 L199 163Z"/>')}${zone('Legs','<path d="M118 324 L154 339 L148 413 L142 477 Q144 494 108 491 Q102 483 117 474 L114 410Z"/><path d="M202 324 L166 339 L172 413 L178 477 Q176 494 212 491 Q218 483 203 474 L206 410Z"/>')}${!back?'<path class="body-detail" d="M148 64q12 9 24 0M160 126v61M137 244h46"/>':'<path class="body-detail" d="M160 128v139M133 147l19 25M187 147l-19 25"/>'}</svg><span class="body-caption">${back?'BACK VIEW':'FRONT VIEW'} · GENERAL AREAS</span></div><div class="body-choices"><span class="eyebrow">01 / LOCATE YOUR DISCOMFORT</span><h2>Start with a general area.</h2><p>Tap the figure or choose a label. You don’t need to know the name of a muscle or organ.</p><div class="region-buttons">${['Head',back?'Back':'Chest',...(back?[]:['Abdomen']),'Pelvis','Arms','Legs'].map(r=>`<button class="secondary" data-region="${r}" aria-pressed="${chosenRegion===r}">${r==='Head'?'Head & neck':r==='Arms'?'Arms & hands':r==='Legs'?'Legs & feet':r} </button>`).join('')}</div><button class="secondary" onclick="bodySide=bodySide==='front'?'back':'front';render()"> Show ${back?'front':'back'}</button><p class="fine">Location guides browsing. It cannot identify the cause of pain.</p></div></div>`}
bodyMap=function(){return simpleBody()};
bodyPage=function(){return `${title('YOUR BODY, EASIER TO EXPLORE','Start broad. Explore deeper.','Choose the level of detail that feels helpful to you.')}<div class="atlas-switch" role="group" aria-label="Atlas detail"><button aria-pressed="${atlasMode==='simple'}" onclick="setAtlas('simple')"> Simple body map <small>Find a general area</small></button><button aria-pressed="${atlasMode==='detailed'}" onclick="setAtlas('detailed')"> Detailed 3D atlas <small>Explore anatomical structures</small></button></div><section class="card">${atlasMode==='simple'?simpleBody():'<p class="muted">Rotate and zoom to explore. Select a structure to locate it more precisely; structure selection does not establish a diagnosis.</p><iframe class="anatomy-frame full" src="anatomy.html" title="Detailed interactive 3D anatomy explorer"></iframe>'}</section><div id="region-result" class="region-result" aria-live="polite"></div><div class="notice danger">Sudden severe pain, chest pressure, trouble breathing or new weakness? <a href="#emergency">Get emergency help </a></div>`};
region=function(r){if(!location.hash.startsWith('#body')){location.hash='body';setTimeout(()=>region(r),60);return}chosenRegion=r;document.querySelectorAll('[data-region]').forEach(el=>{el.classList.toggle('active',el.dataset.region===r);el.setAttribute('aria-pressed',String(el.dataset.region===r))});const groups={Head:['Brain and Nerves','Ear, Nose and Throat','Eyes and Vision'],Chest:['Blood, Heart and Circulation','Lungs and Breathing'],Abdomen:['Digestive System'],Pelvis:['Female Reproductive System','Male Reproductive System','Kidneys and Urinary System'],Back:['Bones, Joints and Muscles','Brain and Nerves'],Arms:['Bones, Joints and Muscles','Brain and Nerves'],Legs:['Bones, Joints and Muscles','Blood, Heart and Circulation']}[r]||[];$('#region-result').innerHTML=`<section class="card"><span class="eyebrow">02 / EXPLORE RELATED TOPICS</span><h2>${esc(r)}: choose a body system</h2><p>These categories can help you find explanations of symptoms and conditions. They are not ranked causes or a diagnosis.</p><div class="chips">${groups.filter(g=>dirGroups.includes(g)).map(g=>`<button class="chip" data-body-group="${esc(g)}">${esc(g)} </button>`).join('')}<button class="chip" onclick="dirState.group='';dirSearch('${r==='Back'?'back pain':r==='Head'?'headache':r.toLowerCase()+' pain'}')">Search related pain topics </button></div></section>`;document.querySelectorAll('[data-body-group]').forEach(b=>b.onclick=()=>{dirState.group=b.dataset.bodyGroup;dirState.kind='';dirState.letter='';dirSearch('')});$('#region-result').scrollIntoView({behavior:get('prognos-motion',false)?'instant':'smooth',block:'nearest'})};
// Progressive disclosure preserves the exact supplied source wording.
function readableSource(s,name){const paragraphs=s.text.split(/\n\s*\n/).filter(p=>p.trim());const first=paragraphs.shift()||'';return `<section class="card readable"><span class="eyebrow">AT A GLANCE · ${esc(s.source.name)}</span><h2>Understanding ${esc(name)}</h2>${textParagraphs(first)}${paragraphs.length?`<details class="reading-section" ${simple?'':'open'}><summary>Read the fuller explanation <span>${paragraphs.length} short sections</span></summary>${paragraphs.map(p=>textParagraphs(p)).join('')}</details>`:''}${s.sections.map(x=>`<details class="reading-section" ${simple?'':'open'}><summary>${esc(x.title)}</summary>${textParagraphs(x.text)}</details>`).join('')}${directorySource(s.source)}</section>`}
const comfortDirectoryArticle=directoryArticle;
directoryArticle=function(id,treatments=false){let html=comfortDirectoryArticle(id,treatments);const e=directoryById.get(id),d=dirDetails?.[id];if(!e||treatments)return html;if(dirTab==='overview'&&d?.summaries.length){const start=html.indexOf('<div class="stack">'),end=html.lastIndexOf('<p class="fine">Educational information');if(start>=0&&end>start)html=html.slice(0,start)+`<div class="stack">${d.summaries.map(s=>readableSource(s,e.name)).join('')}${appointmentCard()}</div>`+html.slice(end)}return html};
function appointmentCard(){return `<section class="card appointment-card"><span class="eyebrow">TURN READING INTO A CONVERSATION</span><h2>Bring a clearer picture to your appointment.</h2><p>Write down when symptoms started, how often they happen, and what makes them better or worse. Bring a list of medicines and supplements, and put your most important questions first.</p><div class="question-prompts"><span>What else might explain my symptoms?</span><span>What is the next step, and when should I follow up?</span><span>Which changes should make me seek help sooner?</span></div><a class="link" href="https://health.nih.gov/health-topics-a-z/prepare-for-appointment" target="_blank" rel="noopener">Appointment preparation · National Institutes of Health </a><p class="fine">Prognos preparation prompts, informed by NIH patient guidance; not a clinical assessment.</p></section>`}
const comfortRender=render;
render=function(){comfortRender();if(location.hash.startsWith('#condition/')){const tools=document.querySelector('.article .tools');if(tools&&!document.querySelector('#reading-glossary'))tools.insertAdjacentHTML('afterend',`<details id="reading-glossary" class="reading-section"><summary>Medical words, made clearer</summary><dl><dt><a href="https://www.cancer.gov/publications/dictionaries/cancer-terms/def/diagnosis" target="_blank" rel="noopener">Diagnosis · National Cancer Institute </a></dt><dd>Identifying a disease or condition from symptoms, history and clinical assessment.</dd><dt><a href="https://medlineplus.gov/ency/article/002215.htm" target="_blank" rel="noopener">Acute · MedlinePlus </a></dt><dd>Sudden; symptoms may appear or change rapidly.</dd><dt><a href="https://medlineplus.gov/ency/article/002312.htm" target="_blank" rel="noopener">Chronic · MedlinePlus </a></dt><dd>Continuing over a long time.</dd></dl><a href="https://medlineplus.gov/appendixa.html" target="_blank" rel="noopener">Medical word meanings · MedlinePlus, U.S. National Library of Medicine </a></details>`)}document.querySelectorAll('.tools button').forEach(b=>{if(b.textContent.includes('Short overview')||b.textContent.includes('Full source summary')||b.textContent.includes('Plain language')||b.textContent.includes('Detailed summary'))b.onclick=()=>preference('simple',!simple)})};
render();
